var IQ = [];
function Q(kind, text, example, extra) { var q = {id:'q' + IQ.length, kind:kind, text:text, example:example}; if (extra) for (var k in extra) q[k] = extra[k]; IQ.push(q); }
var STORY_KINDS = ['intro','motivation','strengths','weakness','hire','competency','followup'];
Q('intro','Tell me about yourself.',{noexp:'Thank you for having me. I\'m in my final year of college studying Business and IT, and outside lessons I help run a youth club on Fridays, which has taught me to be organised and to talk to all kinds of people. I\'m interested in the {role} role because it would let me use those skills in a real workplace. I\'m reliable, I take feedback well, and I\'d love the chance to learn from your team.',entry:'Thank you for having me. I recently finished my studies in Business, and for the past year I\'ve worked part-time in a busy cafe, where I learned to stay calm and organised under pressure. I\'m applying for the {role} role because I want to build a career where I can use those skills every day. I learn quickly, and I\'m keen to contribute.',some:'Thank you. I\'ve worked for around three years in customer-facing roles, most recently as a team member at a regional retailer, where I trained new starters and helped our branch improve its service scores. I\'m now looking for a {role} role where I can take on more responsibility, and I think my mix of experience and reliability would be a strong fit.',exp:'Thank you. Over the last eight years I\'ve moved from entry-level roles into leading a team of six, and I\'ve delivered improvements such as cutting turnaround times by 25%. I\'m excited about this {role} role because it lets me apply that experience in a new setting. I\'m known for being calm under pressure and for developing people.'});
Q('intro','Can you walk me through your background and what brought you here today?',{noexp:'Of course. I\'ve just finished college, where I studied Business and enjoyed group projects most. I also volunteered at a community centre, which showed me I enjoy helping people. That led me to the {role} role, as I want to build experience in a real team.',entry:'Of course. After finishing college, I took a part-time role in retail where I learned customer service and teamwork. I realised I wanted to focus on the {role} area, so I started a short course alongside work. That brought me here today, to apply that learning.',some:'Of course. I started in an admin role, moved into customer support, and for the last year I\'ve coordinated a small team. I\'ve enjoyed the problem-solving most, which is why I\'m interested in this {role} role and the chance to specialise.',exp:'Of course. I began in front-line roles, moved into team leadership after three years, and for the last two years I\'ve managed projects across two sites. I\'m now looking for a {role} role with more scope, and what attracted me to this one is the focus on developing people.'});
Q('motivation','Why do you want to be a {role}?','I\'ve enjoyed this kind of work ever since I helped organise events at my college, because I like turning a plan into something people enjoy. That experience showed me I\'m good at communicating and staying organised. As a {role}, I\'d be able to do that every day, and I\'m excited to keep learning from experienced colleagues.');
Q('motivation','What attracted you to this {role} opportunity?','Two things attracted me. First, the role involves working directly with people, which I enjoy, as I found when I volunteered at a youth club. Second, I\'ve read that your team supports training, and I want to keep developing. I believe I could contribute straight away while I learn.');
Q('motivation','Why do you want to work in this area?','I\'m interested in this area because I like seeing the direct effect of good work. For example, when I helped a local club redesign its flyers, their event attendance rose. That showed me that skills in this field really matter, and I\'d like to build a career where I can do that every day.');
Q('strengths','What would you say are your greatest strengths?','My biggest strengths are reliability and communication. For example, in my part-time job I\'ve covered shifts at short notice and I\'ve never missed one, and colleagues often ask me to explain things to new starters. In a {role} role, I think both would help me support the team.');
Q('strengths','What would people who know you well say is your best quality?','I think they\'d say I\'m calm. For instance, when our group presentation lost its slides ten minutes before we presented, I stayed calm, split up the work, and we rebuilt it in time. I think staying calm under pressure would be valuable as a {role}.');
Q('weakness','What is a weakness you are working on?','I used to find it hard to ask for help, because I wanted to do everything myself. That sometimes slowed me down. So I\'ve started asking one question early on each new task, and my supervisor has noticed I finish more quickly. I\'m still practising, but it\'s become much easier.');
Q('weakness','Tell me about an area you want to improve.','I want to improve my public speaking. I get nervous when presenting, so last term I volunteered to present at every group project. I practised aloud beforehand, and my last presentation received positive feedback. I\'m still working on it, but it\'s getting easier each time.');
Q('hire','Why should we hire you?','I think I\'d bring reliability, a willingness to learn, and good communication. For example, in my last role I was asked to train two new colleagues after only three months, which shows my manager trusted me. I\'d bring the same commitment to this {role} role and to your team.');
Q('hire','What makes you different from other candidates?','What sets me apart is that I combine practical experience with a real willingness to learn. I\'ve worked in a busy team, and I\'ve also taught myself new skills in my own time, like building a simple website for a local club. I\'d bring that initiative to this {role} role.');
Q('hire','Where do you hope to be in three years?','In three years, I\'d like to be confident and capable in my {role} role, and ready to take on more responsibility, perhaps training newer colleagues. To get there, I plan to learn as much as I can in the first year, and to ask for feedback regularly.',{moves:'plan reason',hints:['What do you want to be doing in three years?','What skills will you need to get there?','What would you do in your first year to start?']});
/* competency (STAR) */
Q('competency','Give an example of a time you solved a problem.','At college, our group project was falling behind because two members had stopped replying (Situation). My task was to get us back on track before the presentation (Task). I messaged each person, found out one was struggling with the topic, and split the work so everyone had a clear section with short check-ins (Action). As a result we finished two days early and our teacher praised the clear structure (Result). I learned that it\'s better to ask early than to wait.',{star:true});
Q('competency','Tell me about a time you worked as part of a team.','Last summer I worked in a team of five at a charity event (Situation). My role was to manage the refreshment stall (Task). I made a simple rota so nobody was alone at busy times, and I checked in with the others each hour (Action). We raised 20% more than the previous year, and the organiser thanked us (Result). I learned that a small plan makes teamwork much easier.',{star:true});
Q('competency','Tell me about a difficult situation and how you handled it.','At my part-time job, a customer became angry about a long wait (Situation). I needed to calm them and keep the queue moving (Task). I listened without interrupting, apologised, and offered a free drink while I fetched their order (Action). They thanked me before they left and my manager noticed (Result). I learned that listening first often solves half the problem.',{star:true});
Q('competency','Tell me about a time you made a mistake. What happened?','In a school project I once entered the wrong figures into our shared spreadsheet (Situation). I was responsible for the results page (Task). When I noticed, I told the group straight away, corrected the figures, and set up a second check for future entries (Action). We fixed it before the deadline and the project still scored highly (Result). I learned that being honest quickly stops mistakes growing.',{star:true});
Q('competency','Give an example of a time you had to meet a tight deadline.','Last term, I had three assignments due in the same week (Situation). My goal was to hand them all in on time without lowering the quality (Task). I listed each task, gave each a time slot, and worked on the hardest first (Action). I submitted all three a day early and received good marks (Result). I learned that planning matters more than rushing.',{star:true});
Q('competency','Tell me about a time you received critical feedback.','In my first job, my supervisor told me I was too quiet when speaking to customers (Situation). I needed to become more confident (Task). I practised greetings with a colleague, and set myself a goal to start every conversation (Action). After a month, my supervisor said I was much more confident, and my customer feedback improved (Result). I learned to see feedback as help.',{star:true});
Q('competency','Describe a time you took the initiative.','At my youth club, the equipment cupboard was always a mess (Situation). Nobody had been asked to fix it, but I thought it was slowing everyone down (Task). I stayed behind one evening, sorted everything, and made labels (Action). Sessions then started faster, and the leader asked me to organise the next storeroom (Result). I learned that small improvements are worth making.',{star:true});
Q('competency','Tell me about a time you had to learn something new quickly.','When my part-time job switched to a new till system, I had two days to learn it (Situation). I needed to serve customers confidently by Saturday (Task). I asked a colleague to walk me through it, wrote myself a one-page guide, and practised on quiet shifts (Action). By Saturday I was serving without help, and I later trained two others (Result). I learned how useful it is to ask for a demonstration.',{star:true});
Q('competency','Give an example of a time you persuaded someone to see things your way.','In a group presentation, a teammate wanted to use text-heavy slides (Situation). I thought pictures would work better (Task). I made one sample slide each way and showed the group how easy the visual one was to read (Action). They chose the visual slides, and our teacher said they were clear (Result). I learned that showing is more persuasive than arguing.',{star:true});
Q('competency','Tell me about a time you paid close attention to detail.','While volunteering, I was asked to check names on 200 event tickets (Situation). I needed to make sure there were no mistakes (Task). I checked them twice, once against the list and once aloud with a friend (Action). I found six errors, and the event started without any problems (Result). I learned that a second check is worth the time.',{star:true});
/* situational */
Q('situational','What would you do if you were given a task but did not understand the instructions?','First, I\'d re-read the instructions to see exactly which part is unclear. Then I\'d ask my manager a specific question, for example "Do you want X or Y?", so I don\'t waste their time. Once it\'s clear, I\'d repeat it back to check. If it happened often, I\'d write the steps down for next time.');
Q('situational','What would you do if two colleagues disagreed and it was affecting the team?','I\'d first listen to each person separately to understand their view. Then I\'d suggest they talk it through, and offer to help find a compromise. If it still affected the team, I\'d raise it with my manager, because it\'s important that the work doesn\'t suffer. Finally, I\'d check in a week later to see if things had improved.');
Q('situational','What would you do if you realised you had made an error that nobody else had noticed?','I\'d tell my manager straight away, because hiding it would make it worse. I\'d explain what happened, suggest how to fix it, and fix it as quickly as possible. Afterwards, I\'d think about how to prevent it, for example by adding a check. Being honest builds trust.');
Q('situational','What would you do if you had three urgent tasks and could only finish two?','First, I\'d ask my manager which is most important, rather than guessing. If they weren\'t available, I\'d decide based on deadlines and impact. I\'d then tell the people waiting for the third task and give them a realistic new time. After that, I\'d review how I plan my time so it happens less.');
Q('situational','What would you do if a manager gave you feedback you disagreed with?','I\'d listen carefully first and ask for an example so I understood properly. If I still disagreed, I\'d calmly explain my view with facts, not emotions. I\'d also be open to the idea that they may be right. Either way, I\'d thank them and agree one thing to try.');
Q('situational','What would you do on your first day if nobody had time to show you around?','I\'d introduce myself to the people nearby and ask who the best person to ask would be. I\'d read any guides, and write a list of questions to ask when someone had time. I wouldn\'t wait around. I\'d find small useful tasks to do, and check in with my manager at the end of the day.');
/* technical (generic) */
Q('technical','What skills or tools do you think matter most for a {role}, and how have you started developing them?','For a {role}, I think communication, organisation and the main tools of the job matter most. For example, I\'ve been practising my organisation by planning my week in a calendar, and I\'ve started learning the basics of the tools in my own time. I\'d be keen to learn your specific systems quickly.');
Q('technical','How would you approach learning a new tool or process that you need for this {role} job?','I\'d start with a short guide or demo, then practise on a small real task. I\'d make notes of the steps and ask a colleague to check them. After a few days I\'d try the process without notes. For example, I learned a new till system this way in two days.');
Q('technical','How do you check the quality of your own work before you hand it in?','I use a short checklist: does it answer the request, are the facts or figures right, and is it easy to read? Then I take a short break, and read it again with fresh eyes. For important work, I ask someone else to look at it. This has helped me find errors before others did.');
/* customer */
Q('customer','How would you handle a customer who is angry about a problem?','I\'d stay calm and let them explain without interrupting. Then I\'d acknowledge how they feel, for example "I understand how frustrating that is", and apologise if it was our error. I\'d offer a practical solution, and check they\'re happy with it. Afterwards I\'d tell my manager if it might happen again.');
Q('customer','Tell me about a time you went above and beyond to help someone.','In my cafe job (Situation), an elderly customer was struggling to carry her tray (Task). I carried it for her, found a table near the door, and checked she was comfortable (Action). She thanked me and told my manager, who mentioned it at our next team meeting (Result). It taught me that small actions make a big difference.',{star:true,moves:'situation task action result'});
Q('customer','What does excellent customer service mean to you?','To me, excellent service means making people feel listened to and solving their problem quickly. For example, I try to greet each customer, ask what they need, and check at the end that they\'re happy. In a {role} role, I\'d make that my standard every shift.',{moves:'reason example'});
Q('customer','A customer asks for something we cannot provide. What do you do?','I\'d apologise, explain clearly why I can\'t do it, and then focus on what I can do. For example, "Unfortunately we don\'t stock that, but I can order it for you or suggest something similar." I\'d make sure they leave with a solution, not just a "no".',{moves:'apologise solution'});
Q('customer','How do you stay calm when it gets very busy?','I take a breath and focus on one customer at a time. I prioritise quick tasks first and let waiting customers know I\'ll be with them shortly. For example, on busy Saturdays at my job, I used a simple order list so nothing was forgotten. Calm, clear communication stops stress spreading.',{moves:'plan reason'});
/* leadership */
Q('leadership','Tell me about a time you led others.','At school, I led a group of six for a fundraising project (Situation). We needed to raise £300 in a month (Task). I split the jobs by strengths, held a weekly ten-minute check-in, and kept everyone updated (Action). We raised £420 and the teacher asked us to repeat it next year (Result). I learned that leading is mostly about clear communication.',{star:true,moves:'situation task action result'});
Q('leadership','How would you motivate a team member who seems disengaged?','I\'d talk to them privately and ask how they\'re finding things, without judging, because people rarely open up in public. Then I\'d listen for the cause, such as workload, boredom or confidence. I\'d agree one practical change, like a new responsibility, and check in regularly. People usually re-engage when they feel heard and trusted.');
Q('leadership','How would you handle a disagreement between two people on your team?','I\'d speak to each person separately to hear their view, and then bring them together to agree what the shared goal is. I\'d keep the discussion on the work and not the personalities. Then we\'d agree one action each, and I\'d check in a week later.');
Q('leadership','How do you decide what to delegate?','I think about who has the right skills and who could grow from the task. I delegate tasks that others can do well, and keep the ones that need my specific judgement. I explain the goal, the deadline and what a good result looks like, and then I check in without hovering.');
Q('leadership','How would you deliver difficult news to your team?','I\'d tell them promptly and honestly, in person if possible, and explain the reason clearly. I\'d acknowledge how they might feel, and then explain what happens next. I\'d also make time for questions, because uncertainty is worse than bad news.');
/* creative */
Q('creative','Tell me about a creative idea you are proud of.','I\'m proud of a poster series I designed for a school charity day. I noticed people ignored text-heavy posters, so I used one bold image and one short question on each. Attendance was higher than the previous year, and a teacher asked to use the posters again. It taught me that simple ideas often work best.',{star:true,moves:'situation action result'});
Q('creative','How do you come up with ideas when you feel stuck?','I change my environment first, for example going for a walk. Then I write down ten quick, bad ideas without judging them, because one often leads to a better one. I also look at how other fields solve similar problems. Finally, I test the best idea with someone else.');
Q('creative','How do you respond when someone criticises your creative work?','I listen without defending, and ask what specifically isn\'t working. I separate my feelings from the work. Then I decide which points improve the goal of the piece. For example, a teacher once said my logo was too busy, so I simplified it and it became much stronger.');
Q('creative','Walk me through your process from first brief to finished piece.','I start by clarifying the brief and the audience. Then I research and sketch several rough ideas, and pick the strongest two to develop. I share a draft early to get feedback, refine it, and check it against the brief. Finally, I check details and deliver on time.');
Q('creative','How would you make something original when similar ideas already exist?','I\'d first study what exists so I know what\'s been done. Then I\'d look for an angle that others haven\'t used, for example a different audience or a surprising format. I\'d test it quickly with a small sample, and adjust. Originality often comes from combining ideas.');
/* role-specific */
function R(fam, text, ex) { Q('role', text, ex, {family:fam}); }
R('marketing','What makes social media or marketing content effective?','Effective content starts with knowing the audience. For example, short, visual posts that solve a problem or spark emotion tend to get more engagement than posts that only promote. I\'d also check analytics such as reach and saves to see what works, and adapt.');
R('marketing','How would you measure whether a campaign worked?','I\'d set a clear goal first, such as 500 new followers or 100 sign-ups. Then I\'d track the matching measures, like reach, engagement and conversions, and compare them to a baseline. Afterwards I\'d summarise what worked and what to change next time.');
R('marketing','Which brand do you think markets itself well, and why?','I think Innocent Drinks does it well because its tone is friendly and consistent across packaging and social media. It talks to customers like people, so they feel part of a community. For a {role}, I\'d take the lesson that a clear voice builds trust.');
R('hospitality','How would you cope in a very busy service with several tables waiting?','I\'d stay calm and prioritise: greet each table quickly, even if only to say I\'ll be with them shortly. Then I\'d take drinks first, because that keeps people happy, and communicate with the kitchen. I\'d ask a colleague for help if needed, and keep standards for hygiene.');
R('hospitality','What does great hospitality look like to you?','To me it means guests feel welcome and looked after from the moment they arrive. That includes a friendly greeting, quick service, and noticing small things, such as a guest who needs another napkin. It also means solving problems calmly, so guests leave wanting to return.');
R('hospitality','How would you handle a guest who tells you they have a food allergy?','I\'d take it very seriously. I\'d thank them, ask exactly what they\'re allergic to, and check with the kitchen about ingredients and cross-contact before recommending anything. I\'d tell the kitchen team clearly, and double-check the dish before it\'s served. If I\'m not sure, I\'d say so.');
R('retail','A customer is looking for a product we have run out of. What do you do?','I\'d apologise and check whether another branch or the warehouse has it. If not, I\'d offer to order it, or suggest a similar product, explaining the difference. I\'d take their details if they want to be told when it\'s back in stock, and thank them for their patience.');
R('retail','How would you stay accurate and motivated on a busy Saturday?','I\'d plan my tasks at the start of the shift, and focus on one customer at a time. For accuracy, I\'d double-check totals and returns. To stay motivated, I\'d remind myself that busy days are when good service matters most, and take my breaks so that I\'m fresh.');
R('retail','How would you help increase sales without being pushy?','I\'d ask customers what they\'re looking for, and then recommend items that suit their needs, for example a matching accessory. I\'d be honest if something wasn\'t right for them, because trust brings people back. Good advice usually leads to more sales than pressure.');
R('tech','Describe how you would investigate a problem if something that worked yesterday has stopped working.','First, I\'d find out what changed: updates, settings, or new data. I\'d reproduce the problem and read any error messages. Then I\'d test one possibility at a time, and undo changes if needed. Once fixed, I\'d document the cause so it doesn\'t happen again.');
R('tech','How do you explain a technical idea to a non-technical person?','I start with what it does for them, not how it works. I use an everyday comparison, for example describing a database as a very organised filing cabinet. I avoid jargon, check they\'re following by asking questions, and offer more detail only if they want it.');
R('tech','How do you keep your technical skills up to date?','I set aside a few hours a week to learn something new, usually by building a small project. I follow a few reliable blogs and courses, and I ask for feedback from people with more experience. For example, I taught myself the basics of Python this way.');
R('creative','Walk me through how you would respond to a creative brief.','I\'d read it twice, then clarify the goal, audience and deadline. I\'d research the field, sketch a few directions, and share early drafts for feedback. I\'d keep checking the work against the brief, and finish with a clean, polished version.');
R('creative','How do you handle feedback that changes your concept completely?','I try not to take it personally. I\'d ask what\'s behind the change, such as the audience or budget, and see whether I can keep the strongest part of the idea. Then I\'d make a new version quickly. Often the second concept is better because it\'s clearer.');
R('creative','Tell me about a piece of work you are proud of and what it shows about your style.','I\'m proud of a short film I made for a college project about a day in the life of a market trader. It shows my style: simple, close-up shots and real voices rather than narration. It was shown at our end-of-year event, and people said it felt honest.');
R('sport','How would you plan a training session for a group with different abilities?','I\'d start with a warm-up everyone can do, then use drills with levels, for example an easier and harder version of the same exercise. I\'d mix groups so that stronger players help others, and I\'d give each person a personal goal. Finally, I\'d finish with a cool-down and ask for feedback.');
R('sport','How would you handle a player who keeps arriving late or not trying?','I\'d speak to them privately, without embarrassing them, and ask what\'s going on. Then I\'d explain how it affects the team and agree one clear expectation. I\'d praise improvements, and if nothing changed, I\'d involve a parent or manager. Most of the time there\'s a reason behind it.');
R('sport','How do you give feedback to someone after a poor performance?','I start with something specific that went well, then identify one thing to work on, rather than a long list. I focus on the next step, for example "Let\'s practise passing under pressure on Tuesday". I keep my tone calm, and ask how they felt it went, because players often know.');
R('care','How would you support someone who is upset or struggling?','I\'d stay calm, listen without rushing, and get down to their level if they\'re a child. I\'d acknowledge their feelings, for example "I can see you\'re upset", and give them time. If the problem was beyond me, I\'d follow procedure and tell the right person.');
R('care','How do you make sure the people in your care stay safe and supported?','I follow the safeguarding procedures, stay aware of who is where, and report any concern straight away. I also get to know each person\'s needs, so that I notice if something changes. Clear communication with colleagues and families is a big part of keeping people safe.');
R('care','How would you communicate with a parent or carer who is worried?','I\'d listen first and thank them for raising it. Then I\'d explain clearly what we\'re doing, using plain language, and agree a next step, such as updating them tomorrow. If I couldn\'t answer, I\'d say so and find the right person. Being honest and calm builds trust.');
R('management','How do you plan a project and keep it on track?','I start by defining the goal, deadline and key tasks, then I assign owners and dates. I use a simple tracker and check progress weekly. When something slips, I raise it early and adjust the plan, because small delays are easier to fix than big ones.');
R('management','What would you do if a project was going to miss its deadline?','I\'d find out why, and what could be dropped, simplified or helped. Then I\'d tell the stakeholders early, with a realistic new date and options, rather than waiting. Afterwards, I\'d review what caused the delay so that the next plan is better.');
R('management','How do you keep a team informed and motivated?','I keep communication regular and simple, for example a short weekly update and an open door for questions. I give credit for good work, and make sure each person understands how their job connects to the goal. People stay motivated when they feel trusted and informed.');
R('general','What do you think a typical day looks like for a {role}?','I imagine a {role} starts by checking what is most urgent, then spends the day on a mix of planned tasks and unexpected requests, so organisation matters. There would also be time working with colleagues or customers, and some time to review how things went. I\'d plan my day each morning and keep a short list of priorities.');
R('general','What would you want to achieve in your first 30 days as a {role}?','In my first 30 days, I\'d focus on learning: how the team works, the main tools and who to ask for help. Then I\'d take on one small task and complete it well, so that people can trust me. I\'d also ask my manager for feedback after two weeks, so I can improve early.');
R('general','What do you think is the hardest part of being a {role}, and how would you handle it?','I think the hardest part is probably balancing several demands at once while keeping standards high. I\'d handle it by planning my time, asking early when I\'m unsure, and checking my work before I finish. For example, at college I managed three deadlines in one week by listing tasks and starting with the hardest.');
R('business','How do you keep yourself organised when you have several tasks at once?','I write a list at the start of the day and mark tasks by urgency and importance. I use a calendar for deadlines, and I block time for the hardest task. If something new comes in, I re-prioritise instead of just adding it. This stops anything being forgotten.');
R('business','What would you do if you realised a confidential document had been sent to the wrong person?','I\'d tell my manager immediately. I\'d contact the person who received it, politely ask them to delete it, and note what happened. Then I\'d help find how the mistake happened, for example a similar name, so that we add a check. Speed and honesty matter most.');
R('business','How do you make sure your work is accurate?','I double-check figures and names against the source, and I use checklists for repeated tasks. Where possible, I ask someone to review important work. I also leave a short gap before a final check, because I spot more errors with fresh eyes.');

/* ---------- Helpers ---------- */
function pickWeighted(items, weightFn, rng) {
  var w = items.map(weightFn), sum = w.reduce(function (a, b) { return a + b; }, 0);
  if (!items.length) return null;
  var r = (rng || SW.rand)() * sum;
  for (var i = 0; i < items.length; i++) { r -= w[i]; if (r <= 0) return items[i]; }
  return items[items.length - 1];
}
function fill(text, map) { return String(text).replace(/\{(\w+)\}/g, function (m, k) { return map[k] != null ? map[k] : m; }); }
function trainsOf(s) {
  var t = (CAT_TRAINS[s.cat] || []).slice();
  if (s.moves.indexOf('detail') >= 0 && t.indexOf('specificity') < 0) t.push('specificity');
  if (s.moves.indexOf('summarise') >= 0 && t.indexOf('structure') < 0) t.push('structure');
  if (s.moves.indexOf('clarify') >= 0 && t.indexOf('clarity') < 0) t.push('clarity');
  return t;
}
function interestCats(text) { var out = []; if (!text) return out; for (var c in CAT_INTEREST) if (CAT_INTEREST[c].test(text)) out.push(c); return out; }

/* ctx.* = what an exercise tells the assessor */
function buildScenario(o) {
  o = o || {}; var rng = o.rng || SW.rand, recent = o.recent || [], lastCat = o.lastCat, focus = o.focus, ic = interestCats(o.interests);
  var pool = SCENARIOS.filter(function (s) { return !o.category || o.category === 'all' || s.cat === o.category; });
  var avoid = Math.min(12, Math.floor(pool.length * 0.6));
  var banned = recent.slice(0, avoid);
  var fresh = pool.filter(function (s) { return banned.indexOf(s.id) < 0; });
  if (!fresh.length) fresh = pool.filter(function (s) { return s.id !== recent[0]; });
  if (!fresh.length) fresh = pool;
  var s = pickWeighted(fresh, function (x) {
    var w = 1; if (focus && trainsOf(x).indexOf(focus) >= 0) w += 2; if (ic.indexOf(x.cat) >= 0) w += 0.8; if (x.cat === lastCat) w *= 0.5; return w;
  }, rng);
  var name = o.name || NAMES[Math.floor(rng() * NAMES.length)], map = {name:name};
  return {
    kind:'conversation', id:s.id, cat:s.cat, catLabel:(CATS.filter(function (c) { return c[0] === s.cat; })[0] || [0, s.cat])[1], title:s.title,
    prompt:fill(s.prompt, map), example:fill(s.example, map), name:name,
    focusMatch:!!(focus && trainsOf(s).indexOf(focus) >= 0),
    ctx:{kind:'conversation', tone:s.tone, moves:s.moves, keywords:s.keywords, len:[20, 80]},
    hints:['Who are you speaking to, and what do you want from the conversation?'].concat(s.moves.map(function (m) { return MOVES[m] ? MOVES[m][2] : null; }).filter(Boolean)).concat(['Read it aloud. Does it sound like you?']),
    why:s.moves.map(function (m) { return MOVES[m] && MOVES[m][4]; }).filter(Boolean)
  };
}
/* rebuild an exact scenario (used by "Try again" from History) */
function rebuildScenario(id, name) {
  var s = SCENARIOS.filter(function (x) { return x.id === id; })[0]; if (!s) return null;
  var map = {name:name || NAMES[0]};
  return {kind:'conversation', id:s.id, cat:s.cat, catLabel:(CATS.filter(function (c) { return c[0] === s.cat; })[0] || [0, s.cat])[1], title:s.title, prompt:fill(s.prompt, map), example:fill(s.example, map), name:map.name, focusMatch:false,
    ctx:{kind:'conversation', tone:s.tone, moves:s.moves, keywords:s.keywords, len:[20, 80]},
    hints:['Who are you speaking to, and what do you want from the conversation?'].concat(s.moves.map(function (m) { return MOVES[m] ? MOVES[m][2] : null; }).filter(Boolean)).concat(['Read it aloud. Does it sound like you?']),
    why:s.moves.map(function (m) { return MOVES[m] && MOVES[m][4]; }).filter(Boolean)};
}

function buildWriting(o) {
  o = o || {}; var rng = o.rng || SW.rand, recent = o.recent || [], focus = o.focus;
  var types = WT.filter(function (t) { return !o.type || o.type === 'all' || t.id === o.type; });
  var all = []; types.forEach(function (t) { t.items.forEach(function (it) { all.push({t:t, it:it}); }); });
  var avoid = Math.min(10, Math.floor(all.length * 0.6)), banned = recent.slice(0, avoid);
  var fresh = all.filter(function (x) { return banned.indexOf(x.it.id) < 0; });
  if (!fresh.length) fresh = all.filter(function (x) { return x.it.id !== recent[0]; });
  if (!fresh.length) fresh = all;
  var pick = pickWeighted(fresh, function (x) { return (focus === 'structure' || focus === 'professionalism') ? 1.6 : 1; }, rng);
  return writingFrom(pick.t, pick.it, o.name || NAMES[Math.floor(rng() * NAMES.length)]);
}
function writingFrom(t, it, name) {
  var map = {name:name};
  return {kind:'writing', id:it.id, typeId:t.id, title:t.label, prompt:fill(it.prompt, map), example:fill(it.example, map), name:name,
    ctx:{kind:'writing', tone:t.tone, noEnvelope:t.id === 'coverletter', moves:t.moves, keywords:t.keywords, len:t.id === 'coverletter' ? [60, 150] : (t.id === 'linkedin' ? [35, 110] : [45, 140])},
    hints:['Who is this for, and what do you want them to do after reading it?'].concat(t.moves.map(function (m) { return MOVES[m] ? MOVES[m][2] : null; }).filter(Boolean)).concat(['What one detail would they need to act on this?']),
    why:t.moves.map(function (m) { return MOVES[m] && MOVES[m][4]; }).filter(Boolean)};
}
function rebuildWriting(id, name) {
  for (var i = 0; i < WT.length; i++) for (var j = 0; j < WT[i].items.length; j++) if (WT[i].items[j].id === id) return writingFrom(WT[i], WT[i].items[j], name || NAMES[0]);
  return null;
}

/* ---------- Interview builder ---------- */
var LEVEL_LEN = {noexp:0.8, entry:0.9, some:1, exp:1.05};
function qInstance(q, o) {
  var fam = o.fam, role = o.role, level = o.level, K = IKIND[q.kind], map = {role:role};
  var ex = q.example && typeof q.example === 'object' ? (q.example[level] || q.example.entry) : q.example;
  var text = fill(q.text, map);
  if (level === 'noexp' && (q.kind === 'competency' || q.star)) text += ' (A school, volunteering or personal example is fine.)';
  var words = text.toLowerCase().replace(/[^a-z ]/g, ' ').split(/\s+/).filter(function (w) { return w.length >= 5 && ['about', 'would', 'should', 'there', 'their', 'which', 'these', 'could', 'where', 'those', 'person'].indexOf(w) < 0; }).slice(0, 4);
  var rt = role.toLowerCase().replace(/[^a-z ]/g, ' ').split(/\s+/).filter(function (w) { return w.length > 2 && ['and', 'the', 'for', 'assistant', 'apprentice'].indexOf(w) < 0; });
  var f = K, lf = LEVEL_LEN[level] || 1, moves = (q.moves || K.moves).split(' ');
  return {kind:'interview', qid:q.id, qkind:q.kind, id:q.id, title:text, prompt:text, star:!!(q.star || K.star), example:fill(ex, map), role:role, level:level, family:fam.id,
    ctx:{kind:'interview', qkind:q.kind, tone:'formal', story:!!(q.star || STORY_KINDS.indexOf(q.kind) >= 0), moves:moves, keywords:rt.concat(fam.kws.slice(0, 6), words), len:[Math.round(f.len[0] * lf), Math.round(f.len[1] * lf)], star:!!(q.star || K.star), level:level, role:role, familyTip:fam.tip},
    hints:(q.hints || K.hints).map(function (h) { return fill(h, map); }), why:K.why.slice()};
}
var PLANS = {
 general:['intro', 'motivation', 'strengths', 'competency', 'role', 'hire'],
 competency:['intro', 'competency', 'competency', 'competency', 'competency', 'hire'],
 technical:['intro', 'motivation', 'technical', 'technical', 'role', 'hire'],
 situational:['intro', 'motivation', 'situational', 'situational', 'situational', 'hire'],
 customer:['intro', 'motivation', 'customer', 'customer', 'customer', 'hire'],
 leadership:['intro', 'motivation', 'leadership', 'leadership', 'leadership', 'hire'],
 creative:['intro', 'motivation', 'creative', 'creative', 'creative', 'hire']
};
function buildInterview(o) {
  var rng = o.rng || SW.rand, role = String(o.role || '').trim(), fam = familyOf(role), type = o.type || 'general', level = o.level || 'entry';
  var used = {}; (o.recent || []).forEach(function (id) { used[id] = 1; });
  var chosen = {}, focus = o.focus;
  var plan;
  if (type === 'mixed') {
    var cands = ['competency', 'situational', 'role', 'customer', 'leadership', 'creative', 'technical', 'weakness'], pickK = [];
    while (pickK.length < 3) { var k = cands.splice(Math.floor(rng() * cands.length), 1)[0]; pickK.push(k); }
    plan = ['intro', 'motivation'].concat(pickK, ['hire']);
  } else plan = PLANS[type] || PLANS.general;
  var out = [];
  plan.forEach(function (kind) {
    var pool = IQ.filter(function (q) { return q.kind === kind && (!q.family || q.family === fam.id) && !chosen[q.id]; });
    if (!pool.length && kind === 'role') pool = IQ.filter(function (q) { return (q.kind === 'situational' || q.kind === 'technical') && !q.family && !chosen[q.id]; });
    if (!pool.length) return;
    var fresh = pool.filter(function (q) { return !used[q.id]; }); if (!fresh.length) fresh = pool;
    var q = pickWeighted(fresh, function (x) { return (kind === 'competency' && (focus === 'structure' || focus === 'specificity') && x.star) ? 2 : 1; }, rng);
    chosen[q.id] = 1; out.push(qInstance(q, {fam:fam, role:role, level:level}));
  });
  return out;
}
function rebuildQuestion(att) { // from stored attempt meta (history "Try again")
  var m = att.meta || {}, role = m.role || 'this role', fam = familyOf(role);
  if (m.qkind === 'followup' || /^fu/.test(m.qid || '')) return followUpInstance(att.prompt, role, m.level || 'entry', fam);
  var q = IQ.filter(function (x) { return x.id === m.qid; })[0]; if (!q) return null;
  return qInstance(q, {fam:fam, role:role, level:m.level || 'entry'});
}
function followUpInstance(text, role, level, fam) {
  var q = {id:'fu' + Math.floor(Math.random() * 1e6), kind:'followup', text:text, example:'My own part was deciding how we would split the work and checking in with everyone each day. The outcome was that we finished two days early and the feedback was positive. Next time I would start planning sooner, because early planning made the biggest difference.'};
  var inst = qInstance(q, {fam:fam, role:role, level:level}); inst.qid = q.id; inst.title = text; inst.prompt = text; return inst;
}
/* follow-up based on the user's previous answer */
function makeFollowUp(inst, answer, info) {
  var role = inst.role, fam = {id:inst.family, kws:[], tip:''}; fam = familyOf(role);
  var t = String(answer || '').replace(/[’]/g, '\''), wc = (t.match(/[A-Za-z0-9']+/g) || []).length, text;
  var m = t.match(/\bI (?:\w+ )?(organi[sz]ed|created|led|built|ran|managed|helped|worked (?:on|at|with|in)|volunteered at|started|designed|wrote|developed|taught myself|set up)\s+([^.,;!?\n]{3,60})/i);
  var we = (t.match(/\bwe\b/gi) || []).length, I = (t.match(/\bI\b/g) || []).length;
  if (wc < 35) text = 'Could you give me a specific example of that? Tell me what happened, step by step.';
  else if (we >= 3 && I < we) text = 'You said "we" quite a lot. What did you personally do?';
  else if (info && info.missing && info.missing.indexOf('result') >= 0) text = 'What was the outcome, and how do you know it worked?';
  else if (m) text = 'You mentioned that you ' + m[1].toLowerCase() + ' ' + m[2].trim().split(/\s+/).slice(0, 6).join(' ') + '. What was your own part in that, and what was the result?';
  else if (info && info.relevance != null && info.relevance < 55) text = 'How does that experience relate to working as a ' + role + '?';
  else text = 'What would you do differently next time, and what did you learn from it?';
  return followUpInstance(text, role, inst.level, fam);
}

